<?php /** 출퇴근 요청 승인 */ use App\Core\Db; require_once __DIR__.'/../attendance/common.php'; if(!attendance_is_manager())exit; if(!csrf_check(isset($_POST['_csrf'])?$_POST['_csrf']:''))exit; $pdo=Db::pdo();$id=(int)$_POST['id'];$now=attendance_now(); $st=$pdo->prepare("SELECT * FROM cpms_attendance_requests WHERE id=:id");$st->execute(array(':id'=>$id));$r=$st->fetch(); if($r){$s=$pdo->prepare("SELECT * FROM cpms_attendance_records WHERE employee_id=:e AND work_date=:d LIMIT 1");$s->execute(array(':e'=>$r['employee_id'],':d'=>$r['request_date']));$a=$s->fetch();$ci=$a?$a['check_in']:null;$co=$a?$a['check_out']:null; if($r['request_type']==='check_in'||$r['request_type']==='both')$ci=$r['requested_check_in']; if($r['request_type']==='check_out'||$r['request_type']==='both')$co=$r['requested_check_out']; $m=attendance_minutes($ci,$co); if($a){$u=$pdo->prepare("UPDATE cpms_attendance_records SET check_in=:ci,check_out=:co,status=:st,work_minutes=:m,updated_at=:u WHERE id=:id");$u->execute(array(':ci'=>$ci,':co'=>$co,':st'=>$co?'퇴근완료':'출근중',':m'=>$m,':u'=>$now,':id'=>$a['id']));} else {$i=$pdo->prepare("INSERT INTO cpms_attendance_records(employee_id,work_date,check_in,check_out,status,work_minutes,created_at,updated_at) VALUES(:e,:d,:ci,:co,:st,:m,:c,:u)");$i->execute(array(':e'=>$r['employee_id'],':d'=>$r['request_date'],':ci'=>$ci,':co'=>$co,':st'=>$co?'퇴근완료':'출근중',':m'=>$m,':c'=>$now,':u'=>$now));} $rr=$pdo->prepare("UPDATE cpms_attendance_requests SET status='approved',reviewed_by=:rb,reviewed_at=:ra,updated_at=:u WHERE id=:id");$rr->execute(array(':rb'=>attendance_employee_id($pdo),':ra'=>$now,':u'=>$now,':id'=>$id)); } header('Location: ?r=관리&tab=attendance&atab=requests');